def test_frozen_files_and_loaded_sources():
    path = CANDIDATE / 'candidate-r2-sha256.json'
    assert hashlib.sha256(path.read_bytes()).hexdigest() == 'ae5c2bbb7985adbbb0a2fe402fd712bdeb3194390055bc55f1a13897130cbf9c'
    manifest = json.loads(path.read_text(encoding='utf8'))
    assert len(manifest['files']) == 428
    for relative, meta in manifest['files'].items():
        raw = (CANDIDATE / relative).read_bytes()
        assert len(raw) == meta['bytes'] and hashlib.sha256(raw).hexdigest() == meta['sha256'], relative
    for name, module in tuple(sys.modules.items()):
        if name.startswith(('genshin_app', 'genshin_db', 'genshin_engine', 'genshin_runtime')) and getattr(module, '__file__', None):
            assert Path(module.__file__).resolve().is_relative_to(CANDIDATE / 'src'), name
